import{_ as r,C as i,o,c as s,a5 as l,E as n,j as a,a as d}from"./chunks/framework.BwlBv862.js";const _=JSON.parse('{"title":"阅读与检查直播事件流","description":"","frontmatter":{"title":"阅读与检查直播事件流","docId":"user.live.feed","translationKey":"user.live.feed","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"2291cb390369b29e56df1a5ea5a0eca4b31806d7233905ab4b5ae28bca194277","order":20},"headers":[],"relativePath":"zh/user/live/feed.md","filePath":"zh/user/live/feed.md","lastUpdated":1794611623000}'),c={name:"zh/user/live/feed.md"};function h(p,e,u,f,m,b){const t=i("DemoFrame");return o(),s("div",null,[e[0]||(e[0]=l('<h1 id="read-and-inspect-the-live-feed" tabindex="-1">阅读与检查直播事件流 <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to &quot;阅读与检查直播事件流 {#read-and-inspect-the-live-feed}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>查找事件、检查其字段，并区分显示暂停与直播间断线。先建立<a href="./connections.html">直播连接</a>，或使用当前事件流中已有的事件。事件流是容量有限的工作视图，并非整场直播的完整记录。</p><h2 id="inspect-activity" tabindex="-1">查看活动 <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to &quot;查看活动 {#inspect-activity}&quot;">​</a></h2><ol><li>打开 <strong>实时动态</strong>，在连接状态中确认当前主播。</li><li>选择事件筛选条件：全部事件、聊天、礼物、点赞、关注、加入或其他社交活动。结合搜索，可查找作者、消息、礼物名称或精确的礼物 ID。</li><li>选择 <strong>暂停自动滚动</strong>，在阅读时停止自动滚动。事件仍可继续到达，未读计数也可能增加。该控件不会断开 TikTok 或暂停自动化。</li><li>选择事件，打开检查器。选择自动化字段前，先阅读事件类型和可用详情。并非每个事件都带有聊天文本、礼物信息或观众身份。</li><li>选择观众姓名或头像，查看其已跟踪的资料。详情面板隐藏时，可使用检查器切换控件。</li><li>选择 <strong>恢复自动滚动</strong> 或跳转到未读事件的按钮，返回实时活动。检查事件是否正常到达时，请清空搜索并选择全部事件。</li></ol><p>尽可能通过键盘焦点操作带标签的控件。动态滚动影响阅读时，可暂停滚动。缺少头像时会用姓名首字母代替；识别观众并不需要图片。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>筛选与检查功能均可使用。流量较大时，界面可能只渲染有限窗口，并报告被丢弃的 UI 事件。这些提示描述的是显示情况；不要把可见行数当作账目总数。<a href="./../points/statistics.html">统计分析</a>会另行查询已持久化的聚合数据。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>事件流为空时，请移除筛选、恢复滚动，并检查连接状态。安静的直播间也可能运行正常。重新连接同一主播会保留上下文，切换主播则会更换上下文。<strong>清空动态</strong> 仅清空工作事件流，不会重置积分或统计。通过<a href="./../preferences/troubleshooting.html">诊断</a>调查丢失提示，不要假定所有未显示的行都意味着上游事件丢失。</p>',10)),n(t,{scenario:"feed",locale:"zh",title:"演示：直播事件流"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[d("运行细节 "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "运行细节 {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"本版本最多保留 300 条显示事件，并在等待呈现时暂存最多 900 条。保留策略先移除最旧的非礼物行；只有不剩其他类型时才移除礼物。因此，旧礼物可能比新聊天保留更久。暂停滚动不会停止接收，也不保证保留所有内容。筛选无法恢复已移除的行；丢失提示只说明视图不完整，不能据此重放积分或动作。",-1))])}const g=r(c,[["render",h]]);export{_ as __pageData,g as default};
